/**
 * Hoa lam brush geometry (vine, lotus, curl, wave) taken from the approved "kiln auth" comp.
 * Generated by script, do not edit by hand.
 *
 * Each motif is a set of filled shapes (tapered brush presses), each with its own centreline `c`.
 * A shape is revealed by an SVG mask: the centreline is stroked white and its `stroke-dashoffset`
 * (pathLength = 1) animates, with a mask width `w` always wider than the shape. Coordinates are
 * relative to a corner of the host box (see the JSDoc of each ornament).
 */

export interface BrushStroke {
  /** Filled shape (closed polygon of one brush press). */
  d: string;
  /** Centreline of the press, drawn by the mask. */
  c: string;
  /** Mask stroke width; wide enough to cover the whole shape. */
  w: number;
  /** Stagger step (0..11, in 40ms units; BRAND stagger.list). */
  i: number;
}

/** A round-capped line (wave band); it is its own mask centreline. */
export interface BrushLine {
  d: string;
  /** Stroke width. */
  sw: number;
  /** Opacity relative to the motif. */
  o: number;
  i: number;
}

export interface BrushMotif {
  /** Bounding box [x, y, width, height] of every stroke, used to size the mask region. */
  box: readonly [number, number, number, number];
  turbulenceSeed: number;
  /** Displacement scale of the roughening filter on the stroke edges. */
  roughness: number;
  /** Dense strokes (through the roughening filter). */
  solid: readonly BrushStroke[];
  /** Thin colour wash under the dense strokes. */
  wash: readonly BrushStroke[];
  lines?: readonly BrushLine[];
  /** Ink dots [x, y, radius]. */
  dots: readonly (readonly [number, number, number])[];
}

